3288: 	local _, _, _, completed = GetAchievementInfo(id);
3289: 	if ( not completed and GetPreviousAchievement(id) ) then
3290: 		local prevID = GetPreviousAchievement(id);
3291: 		_, _, _, completed = GetAchievementInfo(prevID);
3292: 		while ( prevID and not completed ) do
3293: 			id = prevID;
3294: 			prevID = GetPreviousAchievement(id);
3295: 			if ( prevID ) then
3296: 				_, _, _, completed = GetAchievementInfo(prevID);
3297: 			end
3298: 		end
3299: 	elseif ( completed ) then
3300: 		local nextID;
3301: 		nextID, completed = GetNextAchievement(id);
3302: 		if ( nextID and completed ) then
3303: 			local newID
3304: 			while ( nextID and completed ) do
3305: 				newID, completed = GetNextAchievement(nextID);
3306: 				if ( completed ) then
3307: 					nextID = newID;
3308: 				end
3309: 			end
3310: 			id = nextID;
3311: 		end
3312: 	end
3313: 
